var ferratasImagenLocal = Object.fromEntries(
  ferratas.filter((ferrata) => ferrata.imagenGrande.startsWith("/images/")).map((ferrata) => [ferrata.id, ferrata.imagenGrande])
);
ferratas.forEach((ferrata) => {
  const activityImage = getActivityMedia(ferrata.id);
  if (activityImage) {
    ferrata.imagen = activityImage.src;
    ferrata.imagenGrande = activityImage.src;
  }
});

// src/lib/mcp/catalog.ts
function fromBarranco(b) {
  return {
    id: b.id,
    type: "barranquismo",
    nombre: b.nombre,
    provincia: b.provincia,
    zona: b.poblacion,
    nivel: `${b.nivel} (${b.nivelExperiencia})`,
    duracion: b.duracion,
    precio: b.precio,
    descripcion: b.descripcionCorta,
    mejorEpoca: b.mejorEpoca,
    url: b.urlInfo,
    descripcionLarga: b.descripcionLarga,
    caracteristicas: b.caracteristicas,
    materialIncluido: b.materialIncluido,
    grupoMinimo: b.grupoMinimo,
    datosTecnicos: {
      clasificacionTecnica: b.clasificacionTecnica,
      desnivel: b.desnivel,
      longitud: b.longitud,
      rapelMaximo: b.rapelMaximo,
      numRapeles: b.numRapeles,
      caudal: b.caudal,
      acceso: b.acceso,
      requisitos: b.requisitos,
      incluye: b.incluye,
      regulacion: b.regulacion
    }
  };
}
function fromFerrata(f) {
  return {
    id: f.id,
    type: "ferrata",
    nombre: f.nombre,
    provincia: f.provincia,
    zona: f.zona,
    nivel: `${f.clasificacion} (${f.dificultad})`,
    duracion: f.duracion,
    precio: f.precio,
    descripcion: f.descripcionCorta,
    mejorEpoca: f.mejorEpoca,
    url: f.urlInfo,
    descripcionLarga: f.descripcionLarga,
    caracteristicas: f.caracteristicas,
    materialIncluido: f.materialIncluido,
    grupoMinimo: f.grupoMinimo,
    datosTecnicos: {
      tipo: f.tipo,
      desnivel: f.desnivel,
      desarrollo: f.desarrollo,
      alturaMaxima: f.alturaMaxima,
      exposicion: f.exposicion,
      aproximacion: f.aproximacion,
      grupoMaximo: f.grupoMaximo,
      reservaObligatoria: f.reservaObligatoria,
      acceso: f.acceso,
      coordenadas: f.coordenadas,
      requisitos: f.requisitos
    }
  };
}
function allActivities() {
  return [
    ...barrancos.map(fromBarranco),
    ...ferratas.map(fromFerrata)
  ];
}
function toSummary(item) {
  const { descripcionLarga, caracteristicas, materialIncluido, grupoMinimo, datosTecnicos, ...summary } = item;
  return summary;
}

// src/lib/mcp/tools/list-activities.ts
var list_activities_default = defineTool({
  name: "list_activities",
  title: "Listar actividades",
  description: "Lista el cat\xE1logo de actividades de aventura (barranquismo, escalada y v\xEDas ferratas) con filtros opcionales por tipo, provincia, texto y precio m\xE1ximo.",
  inputSchema: {
    type: z.enum(["barranquismo", "escalada", "ferrata"]).optional().describe("Tipo de actividad a filtrar."),
    province: z.string().optional().describe("Provincia, p. ej. 'M\xE1laga'."),
    search: z.string().optional().describe("Texto libre a buscar en nombre, zona o descripci\xF3n."),
    maxPrice: z.number().positive().optional().describe("Precio m\xE1ximo por persona en euros."),
    limit: z.number().int().min(1).max(100).default(25).describe("N\xFAmero m\xE1ximo de resultados.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ type, province, search, maxPrice, limit }) => {
    const q = search?.toLowerCase().trim();
    const results = allActivities().filter((a) => type ? a.type === type : true).filter((a) => province ? a.provincia.toLowerCase() === province.toLowerCase() : true).filter(
      (a) => q ? `${a.nombre} ${a.zona} ${a.descripcion} ${a.descripcionLarga}`.toLowerCase().includes(q) : true
    ).filter((a) => {
      if (maxPrice == null) return true;
      const value = Number(a.precio.match(/\d+/)?.[0] ?? 0);
      return value > 0 && value <= maxPrice;
    }).slice(0, limit).map(toSummary);
    return {
      content: [{ type: "text", text: JSON.stringify(results, null, 2) }],
      structuredContent: { count: results.length, activities: results }
    };
  }
});

// src/lib/mcp/tools/get-activity.ts
import { defineTool as defineTool2, ToolError } from "npm:@lovable.dev/mcp-js@0.26.2";
import { z as z2 } from "npm:zod@^3.25.76";
var get_activity_default = defineTool2({
  name: "get_activity",
  title: "Detalle de actividad",
  description: "Devuelve la ficha t\xE9cnica completa de una actividad del cat\xE1logo a partir de su identificador.",
  inputSchema: {
    id: z2.string().min(1).describe("Identificador de la actividad, obtenido con list_activities.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ id }) => {
    const activity = allActivities().find((a) => a.id === id);
    if (!activity) throw new ToolError(`No existe ninguna actividad con id "${id}".`);
    return {
      content: [{ type: "text", text: JSON.stringify(activity, null, 2) }],
      structuredContent: { activity }
    };
  }
});

